const POS={chain:[[80,174],[226,174],[372,174],[518,174]],pipeline:[[80,174],[226,174],[372,174],[518,174]],parallel:[[110,128],[285,128],[110,257],[465,195]],boundary:[[85,174],[245,174],[405,174],[515,276]],coherent:[[105,132],[300,200],[495,132],[300,292]],matrix:[[100,160],[300,160],[300,287],[500,160]],dataflow:[[82,175],[230,175],[378,175],[526,175]],mesh:[[160,132],[440,132],[160,270],[440,270]],loop:[[95,143],[295,143],[495,143],[295,285]],layer:[[110,115],[236,170],[362,225],[488,280]],fanout:[[90,195],[360,112],[470,198],[360,282]],erasure:[[90,162],[262,116],[350,265],[510,162]],quorum:[[78,198],[260,198],[447,116],[447,280]],fork:[[95,190],[295,190],[490,116],[490,275]],control:[[90,120],[280,120],[470,260],[190,260]],hierarchy:[[92,114],[270,200],[475,114],[475,281]],tree:[[95,174],[282,174],[490,109],[490,270]],star:[[300,110],[110,247],[300,270],[490,247]]};
const EDGES={parallel:[[0,1],[0,2],[1,3],[2,3]],boundary:[[0,1],[1,2],[2,3],[1,3]],coherent:[[0,1],[2,1],[1,3]],matrix:[[0,1],[2,1],[1,3]],mesh:[[0,1],[0,2],[1,3],[2,3]],loop:[[0,1],[1,2],[2,3],[3,0]],fanout:[[0,1],[0,2],[0,3]],erasure:[[0,1],[1,2],[1,3],[2,3]],quorum:[[0,1],[1,2],[1,3],[2,1]],fork:[[0,1],[1,2],[1,3]],control:[[0,1],[1,2],[2,3],[3,0]],hierarchy:[[0,1],[1,2],[1,3]],tree:[[0,1],[1,2],[1,3]],star:[[0,1],[0,2],[0,3],[1,0],[2,0],[3,0]]};
const arrow=(x1,y1,x2,y2,curve=0)=>{const a=Math.atan2(y2-y1,x2-x1),dx=Math.cos(a),dy=Math.sin(a),sx=x1+dx*38,sy=y1+dy*38,ex=x2-dx*41,ey=y2-dy*41;return path(`M${sx.toFixed(2)} ${sy.toFixed(2)}${curve?`Q${((sx+ex)/2-dy*curve).toFixed(2)} ${((sy+ey)/2+dx*curve).toFixed(2)} `:'L'}${ex.toFixed(2)} ${ey.toFixed(2)}`,'none',C.line,2)+path(`M${(ex-dx*8-dy*4).toFixed(2)} ${(ey-dy*8+dx*4).toFixed(2)}L${ex.toFixed(2)} ${ey.toFixed(2)}L${(ex-dx*8+dy*4).toFixed(2)} ${(ey-dy*8-dx*4).toFixed(2)}`,'none',C.teal,2)};
const shortLines=(v,limit)=>{const words=String(v).split(' ');if(words.length===1){const a=Array.from(v);return a.length>limit?[a.slice(0,limit).join(''),a.slice(limit).join('')]:[v]}const lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>limit&&lines.at(-1)&&lines.length<3)lines.push(w);else lines[lines.length-1]+=(lines.at(-1)?' ':'')+w}return lines;};
export function computingGeometry(courseId,{zh=true,labels=true,focus=-1}={}){const s=COMPUTING_SUBJECTS[courseId];if(!s)return '';const p=POS[s.layout]||POS.chain,edges=s.edges||EDGES[s.layout]||[[0,1],[1,2],[2,3]];let out=s.layout==='boundary'?box(192,90,267,176,'none',10)+path('M212 90V266','none',C.gold,1.5):'';out+=edges.map(([a,b],i)=>arrow(...p[a],...p[b],(s.layout==='quorum'||s.layout==='star')&&i>=3?13:0)).join('');s.nodes.forEach((n,i)=>{const[x,y]=p[i];out+=`<g transform="translate(${x} ${y})">${focus===i?circle(0,0,40,'#f5c96a55',C.gold):''}<g transform="scale(.72)">${computingGlyph(n.kind)}</g></g>`;if(labels)out+=shortLines(n[zh?'zh':'en'],zh?13:22).map((line,j)=>txt(x,y+43+j*13,line,zh?11:9.5)).join('')});return out;}
export function computingVisualFamily(courseId){return COMPUTING_SUBJECTS[courseId]?.family||null;}
export function renderComputingVisual(courseId,{zh=true,mode='full',focus=-1}={}){const s=COMPUTING_SUBJECTS[courseId];if(!s)return '';const title=zh?s.title:s.titleEn,desc=zh?'原創概念架構；箭頭表示資料、控制或信任關係，非實際部署圖或完整設備規格。':'Original conceptual architecture; arrows show data, control or trust relationships, not a deployment blueprint or complete device specification.';return `<svg xmlns="http://www.w3.org/2000/svg" class="computing-subject-visual" viewBox="0 0 600 370" role="img" aria-label="${esc(title+' — '+desc)}" data-course="${esc(courseId)}" data-family="${esc(s.family)}" data-original="true"><title>${esc(title)}</title><desc>${esc(desc)}</desc>${box(1,1,598,368,C.pale,14)}${txt(65,24,courseId.toUpperCase(),10,C.teal)}${txt(456,24,zh?'原創架構圖 · 概念模型':'ORIGINAL CONCEPTUAL ARCHITECTURE',9,C.teal)}${shortLines(title,zh?29:68).map((line,i)=>txt(300,53+i*16,line,zh?16:12)).join('')}<g data-geometry="${esc(courseId)}">${computingGeometry(courseId,{zh,labels:mode!=='icon',focus})}</g>${mode==='icon'?'':txt(300,354,zh?'閱讀資料流、控制流與信任界面；每個關係都需驗證。':'Read data, control and trust boundaries; validate each relationship.',zh?10:9,C.teal)}</svg>`;}
export function renderComputingIcon(courseId,{en=false}={}){const s=COMPUTING_SUBJECTS[courseId];if(!s)return '';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 88 104" class="project-icon" role="img" aria-label="${esc(en?s.titleEn:s.title)}" data-project-icon="${esc(courseId)}" data-subject-art="${esc(courseId)}" data-original="true">${box(1,1,86,86,C.pale,14)}${path('M25 25H62V62H25Z','none',C.line,1.2)}${s.nodes.map((n,i)=>`<g transform="translate(${i%2?63:25} ${i<2?25:63}) scale(.28)">${computingGlyph(n.kind)}</g>`).join('')}${txt(44,100,courseId==='cybersecurity'?'SECURITY':courseId.toUpperCase(),9,C.teal)}</svg>`;}
export function searchComputingSubjects(query='',{limit=100,zh=true}={}){const q=String(query).normalize('NFKC').trim().toLowerCase().slice(0,120),cap=Math.max(0,Math.min(100,Math.trunc(Number(limit)||0)));return Object.entries(COMPUTING_SUBJECTS).filter(([id,s])=>!q||`${id} ${s.title} ${s.titleEn} ${s.family} ${s.focus} ${s.focusEn}`.toLowerCase().includes(q)).slice(0,cap).map(([id,s])=>({id,title:zh?s.title:s.titleEn,titleEn:s.titleEn,family:s.family,focus:zh?s.focus:s.focusEn,diagram:`assets/diagrams/computing-v11/${id}-${zh?'zh':'en'}.svg`,icon:`assets/icons/computing-v11/${id}.svg`}));}
const param=(id,zh,en,min,max,step,value,unit='')=>[id,[zh,en],min,max,step,value,unit];
const model=(title,formula,unit,params,note,question,source='')=>({title,formula,unit,params,note,question,source});
const REF={cache:'https://www.cs.cornell.edu/courses/cs3410/2026sp/notes/caches.html',roofline:'https://docs.nersc.gov/tools/performance/roofline/',gemm:'https://docs.nvidia.com/deeplearning/performance/dl-performance-matrix-multiplication/index.html',raft:'https://raft.github.io/raft.pdf',pqc:'https://csrc.nist.gov/pubs/fips/203/final',dns:'https://www.rfc-editor.org/rfc/rfc1035.html',dp:'https://www.cis.upenn.edu/~aaroth/Papers/privacybook.pdf',kv:'https://developer.nvidia.com/blog/mastering-llm-techniques-inference-optimization/',amdahl:'https://hpc.llnl.gov/documentation/tutorials/introduction-parallel-computing-tutorial',availability:'https://docs.aws.amazon.com/whitepapers/latest/advanced-multi-az-resilience-patterns/availability-zone-independence.html'};
export const COMPUTING_LABS={
 cpPipeline:model(['分支失誤與平均 CPI','Branch misses and average CPI'],'CPI = CPIbase + branch fraction × miss fraction × penalty','cycles/instruction',[param('base','基準 CPI','Base CPI',.2,5,.1,1),param('branches','分支指令比例','Branch instruction fraction',0,50,1,20,'%'),param('miss','分支失誤率','Branch miss rate',0,100,1,5,'%'),param('penalty','失誤增量週期','Extra cycles per miss',1,40,1,15,'cycles')],['固定指令組合與固定失誤成本，失誤的額外週期線性相加。未模擬亂序執行、重疊停頓、記憶體依賴或投機副作用；輸入是人工假設，不是某顆 CPU 的量測值。','Fixed instruction mix and miss cost, with extra miss cycles added linearly. Out-of-order overlap, memory dependencies and speculation side effects are omitted. Inputs are synthetic assumptions, not measurements of a named CPU.'],['若兩種停頓能重疊，直接相加為何可能高估 CPI？','Why can direct addition overestimate CPI when two stall sources overlap?']),
 cpCache:model(['快取平均存取時間','Average cache access time'],'AMAT = hit time + miss fraction × extra miss penalty','ns',[param('hit','命中時間','Hit time',.1,20,.1,1,'ns'),param('miss','未命中比例','Miss fraction',0,100,1,5,'%'),param('penalty','額外未命中懲罰','Extra miss penalty',1,500,1,50,'ns')],['單層阻塞快取，未命中懲罰是命中查詢之後的額外時間，避免重複計算。忽略預取、併發未命中、頻寬飽和及一致性；低 AMAT 不代表全應用程式一定更快。','Single blocking cache. Miss penalty is extra time after the hit lookup, avoiding double counting. Prefetch, concurrent misses, bandwidth saturation and coherence are excluded. Lower AMAT does not by itself imply a faster whole application.'],['命中時間增加但未命中率減半，何時才有收益？','When is halving miss rate worthwhile if hit latency increases?'],REF.cache),
 cpRoofline:model(['GPU Roofline 上界','GPU Roofline upper bound'],'Pbound = min(Ppeak, bandwidth × arithmetic intensity)','TFLOP/s',[param('peak','假設峰值算力','Assumed peak compute',1,2000,1,100,'TFLOP/s'),param('bandwidth','假設記憶體頻寬','Assumed memory bandwidth',10,8000,10,1000,'GB/s'),param('intensity','運算強度','Arithmetic intensity',.1,1000,.1,20,'FLOP/byte')],['十進位 GB 與 TFLOP，運算強度使用同一記憶體層的資料搬移量。這是理想上界，不是實際跑分；精度、稀疏性、占用率、通訊與指令開銷必須與峰值定義一致。','Decimal GB and TFLOP; intensity uses traffic at the same memory level. This is an ideal ceiling, not measured performance. Precision, sparsity, occupancy, communication and instruction overhead must match the peak-performance definition.'],['運算強度低於轉折點時，增加峰值算力為何幫助有限？','Why does higher peak compute help little below the roofline ridge point?'],REF.roofline),
 cpMatmul:model(['張量矩陣乘法工作量','Tensor matrix-product work'],'W ≈ 2 M N K','GFLOP',[param('m','A 的列數 M','Rows of A, M',1,16384,1,1024),param('n','B 的欄數 N','Columns of B, N',1,16384,1,1024),param('k','內積長度 K','Inner-product length K',1,16384,1,1024)],['計算稠密 A(M×K) 與 B(K×N) 的乘法工作量，一次乘加計兩個運算。忽略縮放、偏置、稀疏性、尾端填補及資料搬移；工作量不是執行時間，TPU 或 GPU 的精度與累加規則需另查。','Dense A(M×K) times B(K×N), counting one multiply-add as two operations. Scaling, bias, sparsity, padding and movement are omitted. Operation count is not runtime; TPU/GPU precision and accumulation conventions need separate checks.'],['固定 M、N 而 K 加倍，工作量和輸出大小各如何改變？','If K doubles at fixed M and N, how do work and output size change?'],REF.gemm),
 cpQuorum:model(['多數共識門檻','Majority-consensus threshold'],'Q = floor(N/2) + 1','nodes',[param('nodes','投票節點數 N','Voting nodes N',1,31,1,5)],['固定成員的非拜占庭多數共識，只計投票門檻。需要多數節點彼此通訊且有適當持久日誌；不代表任意故障、網路分割或成員變動都可進展，亦非拜占庭 3f+1 公式。','Non-Byzantine majority consensus with fixed membership; only counts voting quorum. A communicating majority and suitable durable logs are required. It does not guarantee progress under every partition or reconfiguration, and is not the Byzantine 3f+1 model.'],['5 節點失去 2 個可形成多數嗎？兩側分割能同時提交嗎？','Can five voters retain a majority after two fail? Can both sides of a partition commit?'],REF.raft),
 cpErasure:model(['理想抹除碼儲存倍數','Ideal erasure-code storage expansion'],'expansion = (k + m) / k','×',[param('data','資料片段 k','Data fragments k',1,32,1,8),param('parity','冗餘片段 m','Parity fragments m',1,16,1,3)],['等長片段、理想 MDS 編碼，可由任意 k 個完整片段恢復。計算容量倍數，未計中繼資料、小物件填補、修復頻寬或相關失效；可恢復性取決於實際編碼與放置策略，不等於可靠度。','Equal-size fragments with an ideal MDS code recoverable from any k intact fragments. Counts capacity expansion, excluding metadata, small-object padding, repair bandwidth and correlated failure. Recoverability depends on real code and placement, and is not reliability.'],['降低儲存倍數時，修復流量與失效域應如何一起評估？','When reducing expansion, how should repair traffic and failure domains also be assessed?']),
 cpDowntime:model(['30 日可用性錯誤預算','30-day availability error budget'],'budget = 30 × 24 × 60 × (1 − availability)','min/30 days',[param('availability','目標時間可用性','Target time availability',90,99.999,.001,99.9,'%')],['固定 30 日觀察窗、時間型 SLI，分母包含全部觀察分鐘。未納入請求量加權、排除窗、計劃維護或多項 SLO；錯誤預算不是保證，也不能由單一 p99 延遲代替。','Fixed 30-day window with a time-based SLI over all observed minutes. Request weighting, exclusions, planned maintenance and multiple SLOs are omitted. Error budget is not a guarantee and cannot be replaced with a single p99 latency.'],['流量集中於尖峰時，時間可用性和請求成功率為何可能不同？','Why can time availability differ from request success rate when traffic peaks sharply?']),
 cpTail:model(['合成 M/M/1 的 p99 回應時間','Synthetic M/M/1 p99 response time'],'p99 = −ln(0.01) × mean service time / (1 − utilization)','ms',[param('service','平均服務時間','Mean service time',.1,100,.1,2,'ms'),param('utilization','平均使用率 ρ','Mean utilization ρ',0,99,.5,70,'%')],['單一 FCFS 伺服器、Poisson 到達、獨立指數服務時間、無容量限制且 ρ<1。輸出是此合成佇列的等待加服務 p99；真實突發、重試、多核心及長尾不可由這個式子預測。','One FCFS server with Poisson arrivals, independent exponential service, unlimited capacity and ρ<1. The output is waiting-plus-service p99 for this synthetic queue. Real bursts, retries, multicore work and heavy tails cannot be forecast by this formula.'],['使用率接近 100% 時為何尾端延遲快速上升？','Why does tail latency rise sharply as utilization approaches 100%?']),
 cpPqcBytes:model(['ML-KEM-768 額外傳输時間尺度','ML-KEM-768 payload transmission scale'],'t = 8 × (1184 + 1088 + framing) / link rate','ms',[param('framing','示例額外框架位元組','Example extra framing bytes',0,4096,16,256,'bytes'),param('rate','假設有效傳輸速率','Assumed effective transfer rate',.1,10000,.1,10,'Mbit/s')],['1184-byte 封裝公鑰與 1088-byte 密文是 ML-KEM-768 格式量級，只算兩個 payload 與自行設定框架的序列傳輸時間。不是完整 TLS transcript；握手 RTT、混合方案、憑證、CPU 與協定狀態未含，絕不表示密碼強度或實際 TLS 延遲。','The 1184-byte encapsulation key and 1088-byte ciphertext are ML-KEM-768 format sizes. Only serial transmission of those two payloads and chosen framing is counted. This is not a full TLS transcript: RTT, hybrid scheme, certificates, CPU and state are excluded. It says nothing about strength or measured TLS latency.'],['高速本地鏈路和高 RTT 衛星鏈路中，位元組數通常主導同一項成本嗎？','Do payload bytes dominate the same cost on a fast LAN and a high-RTT satellite link?'],REF.pqc),
 cpDns:model(['合成單筆 DNS 快取更新率','Synthetic single-record DNS refresh rate'],'upstream queries/min = 60 λ / (1 + λ TTL)','queries/min',[param('arrival','單筆記錄 Poisson 請求率 λ','Single-record Poisson request rate λ',.01,100,.01,1,'requests/s'),param('ttl','固定 TTL','Fixed TTL',0,3600,1,60,'s')],['自行建立的更新模型：單一記錄、同一快取、固定 TTL，過期後第一個請求觸發刷新。以 TTL 加下一次請求的平均等待時間求更新率。忽略負快取、預取、serve-stale、失敗與多層解析器；這不是 RFC 規定的流量公式。','An original renewal model: one record, one cache, fixed TTL, with the first request after expiry refreshing it. Rate uses TTL plus mean wait for that request. Negative caching, prefetch, serve-stale, failures and resolver layers are omitted. This traffic formula is not prescribed by the RFC.'],['TTL 增加能減少查詢，但快取資料的新鮮度有何代價？','How can a longer TTL reduce queries while affecting freshness?'],REF.dns),
 cpPrecision:model(['資安警報的基率效應','Base-rate effect in security alerts'],'precision = TPR × prevalence / [TPR × prevalence + FPR × (1 − prevalence)]','%',[param('prevalence','合成真實事件基率','Synthetic true-event prevalence',.001,20,.001,.1,'%'),param('tpr','偵測敏感度 TPR','Sensitivity TPR',1,100,.5,95,'%'),param('fpr','良性事件誤報率 FPR','False-positive rate on benign events',.001,20,.001,1,'%')],['二元分類、固定基率與固定 TPR/FPR，根據 Bayes 規則算陽性預測值。所有輸入均為合成且標註定義一致；未含概念漂移、延遲標籤、重複警報或攻擊者行為，不是偵測產品測試結果。','Binary classification with fixed prevalence and TPR/FPR, applying Bayes’ rule to positive predictive value. Inputs are synthetic with consistent label definitions. Drift, delayed labels, duplicate alerts and adversarial behavior are omitted; this is not a detection-product benchmark.'],['敏感度很高但事件非常罕見時，為何大部分警報仍可能是誤報？','Why can most alerts be false even with high sensitivity when real events are rare?']),
 cpLaplace:model(['Laplace 隱私雜訊尺度','Laplace privacy-noise scale'],'b = L1 sensitivity / ε ; E[|noise|] = b','query units',[param('sensitivity','核定 L1 敏感度','Validated L1 sensitivity',.1,100,.1,1,'query units'),param('epsilon','單次查詢 ε','Single-query ε',.05,10,.05,1)],['只顯示 Laplace 機制的尺度與期望絕對雜訊，不抽樣也不處理真實個資。隱私保證依賴正確相鄰資料集定義、全域敏感度及機制實作；多次查詢需算組合預算，ε 並非通用安全分數。','Shows Laplace scale and expected absolute noise only; no sampling or real personal data. Privacy guarantees depend on correct neighboring-dataset definitions, global sensitivity and implementation. Repeated queries require composition accounting; epsilon is not a universal safety score.'],['單次 ε 相同但連續查詢 100 次，能否忽略隱私組合？','Can privacy composition be ignored across 100 queries with the same per-query epsilon?'],REF.dp),
 cpKv:model(['LLM KV 快取容量','LLM KV-cache capacity'],'memory = 2 × batch × layers × tokens × KV heads × head width × bytes/element','GiB',[param('batch','同步序列數','Concurrent sequences',1,128,1,4),param('layers','保留 KV 的層數','Layers retaining KV',1,128,1,32),param('tokens','每序列保留 token','Retained tokens per sequence',128,131072,128,4096),param('heads','KV 頭數','KV heads',1,128,1,8),param('width','每頭維度','Width per head',16,256,8,128),param('bytes','每元素位元組','Bytes per element',1,4,1,2,'bytes')],['固定形狀的解碼快取，係數 2 表示 key 與 value；GQA 使用 KV 頭數而非 query 頭數。未含模型權重、啟用值、頁面碎片、量化尺度及混合／壓縮注意力；只是容量帳，不是本機可執行模型保證。','Fixed-shape decode cache with factor two for keys and values. GQA uses KV heads, not query heads. Weights, activations, page fragmentation, quantization scales and hybrid/compressed attention are omitted. This is capacity accounting, not a guarantee a model will run on a device.'],['把 query 頭數誤當 KV 頭數時，GQA 模型的估值會怎樣偏差？','How does substituting query-head count bias the estimate for a GQA model?'],REF.kv),
 cpAmdahl:model(['HPC 強擴展理想上界','HPC ideal strong-scaling bound'],'speedup = 1 / [serial fraction + (1 − serial fraction) / workers]','×',[param('serial','固定串行比例','Fixed serial fraction',0,100,.1,5,'%'),param('workers','並行工作者數','Parallel workers',1,4096,1,64)],['問題大小固定、串行比例固定，並行部分理想平均分配且完全無通訊或排程開銷。這是 Amdahl 強擴展上界；弱擴展、資料移動、同步與記憶體容量另論，不能據此承諾超級電腦實際加速比。','Fixed problem size and serial fraction with perfect balance and zero communication or scheduling overhead. This is the Amdahl strong-scaling ceiling. Weak scaling, movement, synchronization and memory capacity are separate; it does not promise real supercomputer speedup.'],['增加到無限多工作者時，5% 串行比例的上界是多少？','What is the infinite-worker ceiling with a five-percent serial fraction?'],REF.amdahl),
 cpWire:model(['單一 payload 序列化時間','Single-payload serialization time'],'t = 8 × payload bytes / effective bit rate','µs',[param('payload','單一 payload','Single payload',64,65536,1,1500,'bytes'),param('rate','假設有效位元速率','Assumed effective bit rate',1,800000,1,10000,'Mbit/s')],['只計一個 payload 在固定有效速率上的序列化時間，十進位 Mbit/s。未計線路編碼、headers、傳播、排隊、重傳及多跳；吞吐量、傳播延遲與頻寬是不同概念，不能用此式預估端到端 p99。','Only serialization of one payload at a fixed effective decimal Mbit/s rate. Line coding, headers, propagation, queueing, retransmission and hops are omitted. Throughput, propagation delay and bandwidth differ; this is not an end-to-end p99 estimate.'],['同樣頻寬下，光纜距離增加為何仍會增加端到端延遲？','Why does a longer fiber path increase end-to-end latency at the same bandwidth?']),
 cpRedundancy:model(['獨立副本的理想可用性','Ideal availability of independent replicas'],'A = 1 − (1 − Asingle)^copies','%',[param('single','單一副本假設可用性','Assumed single-replica availability',80,99.99,.01,99,'%'),param('copies','任一即可服務的副本數','Replicas where any can serve',1,8,1,2)],['僅在副本失效完全獨立且任一存活即可正確服務時成立。忽略共同軟體錯誤、電力、網路、資料一致性、切換時間與流量容量；多區部署不等於已驗證獨立，不能拿本式當服務保證。','Requires fully independent replica failures and any surviving replica serving correctly. Common software, power, network, consistency, failover delay and capacity are omitted. Multi-zone deployment does not establish independence; this is not a service guarantee.'],['所有副本依賴同一身分服務時，獨立失效假設還成立嗎？','Does independence hold when every replica depends on one identity service?'],REF.availability)
};
const MAP={cybersecurity:['cpPrecision','cpDowntime'],302:['cpPipeline','cpCache'],303:['cpCache'],304:['cpRoofline'],305:['cpMatmul','cpRoofline'],306:['cpWire','cpMatmul'],307:['cpWire'],308:['cpCache'],309:['cpTail'],310:[],311:['cpAmdahl'],312:['cpWire'],313:['cpTail'],314:['cpAmdahl'],315:['cpAmdahl','cpPipeline'],316:['cpErasure'],317:['cpErasure'],318:['cpWire','cpTail'],319:['cpQuorum'],320:['cpTail'],321:['cpAmdahl','cpTail'],322:['cpCache'],323:['cpTail'],324:['cpTail','cpWire'],325:['cpDowntime','cpTail'],326:['cpAmdahl'],327:[],328:[],329:['cpDowntime','cpRedundancy'],330:['cpRedundancy','cpDowntime'],331:['cpWire'],332:['cpWire'],333:['cpWire'],334:['cpWire'],335:['cpDns'],336:['cpWire'],337:['cpWire'],338:['cpWire'],339:['cpTail'],340:['cpWire'],341:['cpTail'],342:['cpWire'],343:['cpWire'],344:['cpWire'],345:['cpWire'],346:['cpWire'],347:['cpWire'],348:['cpWire'],349:['cpWire'],350:[],351:['cpPrecision'],352:['cpRedundancy'],353:[],354:[],355:[],356:[],357:['cpPqcBytes'],358:['cpPqcBytes'],359:['cpPrecision'],360:['cpPrecision','cpTail'],361:['cpPrecision'],362:['cpPrecision'],363:['cpPrecision'],364:['cpWire'],365:['cpWire'],366:['cpPrecision','cpWire'],367:['cpWire'],368:['cpPrecision'],369:['cpDowntime'],370:[],371:['cpLaplace'],372:['cpWire','cpLaplace'],373:['cpLaplace'],374:['cpAmdahl'],375:['cpWire'],376:['cpCache'],377:['cpCache','cpTail'],378:['cpKv'],379:['cpKv','cpRoofline'],380:[],381:['cpPrecision'],382:['cpCache'],383:['cpTail'],384:['cpMatmul','cpPrecision'],385:['cpTail'],386:['cpCache','cpDns'],387:['cpRoofline'],388:['cpAmdahl'],389:['cpAmdahl','cpWire'],390:['cpAmdahl'],391:['cpErasure','cpWire'],392:['cpRoofline','cpAmdahl'],393:['cpAmdahl','cpCache'],394:['cpRoofline','cpAmdahl'],395:['cpRoofline','cpAmdahl'],396:['cpRoofline','cpAmdahl'],397:['cpWire'],398:['cpWire','cpTail'],399:['cpAmdahl'],400:['cpDns','cpRedundancy']};
export const COMPUTING_COURSE_LABS=Object.freeze(Object.fromEntries(Object.entries(MAP).map(([id,k])=>[id==='cybersecurity'?id:'a'+id,Object.freeze(k)])));
export function computingLabKind(course={},step={}){const kinds=COMPUTING_COURSE_LABS[course.id];if(!kinds?.length)return '';const s=String(step.titleEn||'').toLowerCase(),want=/cache|memory/.test(s)?'cpCache':/quorum|consensus/.test(s)?'cpQuorum':/matrix|tensor/.test(s)?'cpMatmul':/latency|tail/.test(s)?'cpTail':/privacy|epsilon/.test(s)?'cpLaplace':/alert|precision/.test(s)?'cpPrecision':/parallel|scal/.test(s)?'cpAmdahl':/availability|budget/.test(s)?'cpDowntime':/token|inference/.test(s)?'cpKv':'';return kinds.includes(want)?want:kinds[(Math.max(1,Math.trunc(Number(step.sequence)||1))-1)%kinds.length];}
export function calculateComputingLab(kind,v={}){const lab=COMPUTING_LABS[kind];if(!lab)return null;if(lab.params.some(([id,,min,max])=>typeof v[id]!=='number'||!Number.isFinite(v[id])||v[id]<min-1e-9||v[id]>max+1e-9))return NaN;const int=id=>Math.round(v[id]);switch(kind){case 'cpPipeline':return v.base+v.branches*v.miss*v.penalty/10000;case 'cpCache':return v.hit+v.miss*v.penalty/100;case 'cpRoofline':return Math.min(v.peak,v.bandwidth*v.intensity/1000);case 'cpMatmul':return 2*int('m')*int('n')*int('k')/1e9;case 'cpQuorum':return Math.floor(int('nodes')/2)+1;case 'cpErasure':return (int('data')+int('parity'))/int('data');case 'cpDowntime':return 43200*(1-v.availability/100);case 'cpTail':return Math.log(100)*v.service/(1-v.utilization/100);case 'cpPqcBytes':return 8*(1184+1088+v.framing)/v.rate/1000;case 'cpDns':return 60*v.arrival/(1+v.arrival*v.ttl);case 'cpPrecision':{const tp=v.tpr*v.prevalence/10000,fp=v.fpr*(1-v.prevalence/100)/100;return 100*tp/(tp+fp);}case 'cpLaplace':return v.sensitivity/v.epsilon;case 'cpKv':return 2*int('batch')*int('layers')*int('tokens')*int('heads')*int('width')*int('bytes')/(2**30);case 'cpAmdahl':return 1/(v.serial/100+(1-v.serial/100)/int('workers'));case 'cpWire':return 8*v.payload/v.rate;case 'cpRedundancy':return 100*(1-(1-v.single/100)**int('copies'));default:return null;}}
export function computingLabDetail(kind,v,zh=true){const tr=(a,b)=>zh?a:b;if(!COMPUTING_LABS[kind]||!Number.isFinite(calculateComputingLab(kind,v)))return '';switch(kind){case 'cpRoofline':return `${tr('轉折運算強度','Ridge intensity')} ${(v.peak*1000/v.bandwidth).toFixed(2)} FLOP/byte · ${v.bandwidth*v.intensity/1000<v.peak?tr('理想記憶體上界','Ideal memory ceiling'):tr('理想運算上界','Ideal compute ceiling')}`;case 'cpQuorum':return `${tr('可失去的投票節點上限','Maximum lost voters')} ${Math.round(v.nodes)-calculateComputingLab(kind,v)} · ${tr('固定成員、非拜占庭','Fixed membership, non-Byzantine')}`;case 'cpErasure':return `${tr('資料比率','Data fraction')} ${(100*Math.round(v.data)/(Math.round(v.data)+Math.round(v.parity))).toFixed(1)}%`;case 'cpPqcBytes':return `${tr('示例 payload 總數','Example payload total')} ${(2272+v.framing).toFixed(0)} bytes · ${tr('不含 RTT','RTT excluded')}`;case 'cpDns':return `${tr('平均更新間隔','Mean refresh interval')} ${(v.ttl+1/v.arrival).toFixed(2)} s`;case 'cpLaplace':return `${tr('此算例不輸出真實個資、不抽樣','No real personal data or random sampling')}`;case 'cpKv':return `${tr('容量不含權重與啟用值','Excludes weights and activations')}`;case 'cpAmdahl':return `${tr('無限工作者上界','Infinite-worker ceiling')} ${v.serial===0?tr('模型中無界','Unbounded in this model'):(100/v.serial).toFixed(2)+'×'}`;case 'cpTail':return `${tr('平均回應時間','Mean response time')} ${(v.service/(1-v.utilization/100)).toFixed(2)} ms`;default:return tr('本機合成算例；不連線到設備或目標網路。','Local synthetic example; no device or target-network connection.');}}
